```c
#include <stdio.h>
#include <stdlib.h>

#define INF 1000000000

typedef struct {
    int to;
    int next;
} Edge;

int head[300005];
Edge edges[600010];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int order[300005];
int parent_node[300005];
int max_unc[300005];
int min_cov[300005];

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    if (k >= n) {
        printf("0\n");
        return 0;
    }

    // BFS para definir a ordem dos nós e os pais
    int front = 0, back = 0;
    order[back++] = 1;
    parent_node[1] = 0;

    // Usar max_unc temporariamente como visitados
    for (int i = 1; i <= n; i++) max_unc[i] = 0;
    max_unc[1] = 1;

    while (front < back) {
        int u = order[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (!max_unc[v]) {
                max_unc[v] = 1;
                parent_node[v] = u;
                order[back++] = v;
            }
        }
    }

    int low = 0, high = n, ans = n;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        int centers = 0;
        for (int i = 1; i <= n; i++) {
            max_unc[i] = 0;
            min_cov[i] = INF;
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];

            if (max_unc[u] + min_cov[u] <= 2 * mid) {
                max_unc[u] = -INF;
            }

            if (max_unc[u] == mid) {
                centers++;
                min_cov[u] = 0;
                max_unc[u] = -INF;
            }

            int p = parent_node[u];
            if (p != 0) {
                if (max_unc[u] != -INF) {
                    if (max_unc[u] + 1 > max_unc[p]) {
                        max_unc[p] = max_unc[u] + 1;
                    }
                }
                if (min_cov[u] != INF) {
                    if (min_cov[u] + 1 < min_cov[p]) {
                        min_cov[p] = min_cov[u] + 1;
                    }
                }
            }
        }

        if (max_unc[1] >= 0) {
            centers++;
        }

        if (centers <= k) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    printf("%d\n", ans);
    return 0;
}
```

